// 组件只给实际fact头及已知责任，真正政治连续性和Common Action完成另由S3/S6联合门验证。
struct ReliefSources final:TaskGovernanceRead,GovernanceAuthorityRead {
    GovernanceTaskSource source;GovernanceAuthorityApproval approval;bool permit=true;GovernanceContinuityKind continuity=GovernanceContinuityKind::continue_work;bool continuity_missing=false;
    Outcome<GovernanceTaskSource> governance_task_source(const StableId& id)const override{return id==source.acceptance.task_id?Outcome<GovernanceTaskSource>{true,source,{}}:Outcome<GovernanceTaskSource>{false,{},common_failure("UnknownTestTask").error};}
    Outcome<GovernanceWorkCompletion> governance_work_completion(const StableId& id)const override{return source.work&&source.work->fact_id==id?Outcome<GovernanceWorkCompletion>{true,*source.work,{}}:Outcome<GovernanceWorkCompletion>{false,{},common_failure("UnknownTestWork").error};}
    Outcome<GovernanceTaskCompletion> governance_task_completion(const StableId& id)const override{return source.completion&&source.completion->fact_id==id?Outcome<GovernanceTaskCompletion>{true,*source.completion,{}}:Outcome<GovernanceTaskCompletion>{false,{},common_failure("UnknownTestCompletion").error};}
    Outcome<GovernanceContinuityResult> governance_continuity(const StableId&,const StableId&)const override{if(continuity_missing)return {false,{},common_failure("MissingTestContinuity",{},ErrorKind::unsupported_capability).error};return {true,{continuity,{},{}},{}};}
    Outcome<GovernanceAuthorityApproval> governance_authority_approval(const StableId& id)const override{return id==approval.authority_fact_id?Outcome<GovernanceAuthorityApproval>{true,approval,{}}:Outcome<GovernanceAuthorityApproval>{false,{},common_failure("UnknownTestApproval").error};}
    Outcome<GovernanceAuthorityApproval> governance_authority_for_acceptance(const StableId& id,const StableId& actor,Integer revision)const override{if(!permit||actor!=approval.executor_actor_id||revision!=0)return {false,{},common_failure("TestAuthorityDenied").error};return governance_authority_approval(id);}
};
// 每份夹具明确120钱/20粮；资产一直由实际共同原语预留与转移。
struct ReliefFixture:Fixture {
    PublicReliefCatalog relief_catalog;PublicReliefState relief;ReliefSources sources;
    ReliefFixture(){
        common.state().metadata.ruleset_id=dynamic_ruleset_id;
        assert(common.apply_resources({{WalletDelta{"city.wallet",113,true}},{}}).ok);
        auto& p=sources.approval;p.authority_fact_id="approval";p.organization_id="city";p.executor_actor_id="mayor";p.jurisdiction_id="district";p.site_id="town";p.rule_id="appease";p.rule_version="1";p.relief_policy_id="aid";p.public_wallet_id="city.wallet";p.public_inventory_id="city.inventory";p.grain_item_id="grain";p.issued_tick=0;p.offer_expires_tick=1;p.work_ticks=6;p.completion_deadline_ticks=8;p.cash_limit=120;p.grain_limit=10;
        auto& a=sources.source.acceptance;a.fact_id="accept";a.task_id="task";a.contract_id="contract";a.authority_source_fact_id="approval";a.organization_id="city";a.executor_actor_id="mayor";a.jurisdiction_id="district";a.site_id="town";a.rule_id="appease";a.rule_version="1";a.reservation_id="contract";a.work_ticks=6;a.deadline_tick=8;sources.source.task_status="active";
        assert(common.append_fact({"approval","governance_authority_issued","politics"}).ok&&common.append_fact({"accept","governance_task_accepted","tasks"}).ok);relief_catalog.policies.insert("aid",{"aid","town","city","grain",{{"family","workers",120,10}}});
    }
    // 模拟S3回填已经真实预留的terms引用；不在S5重新保存Task状态。
    void reserve(){auto result=reserve_public_relief(common,economy,relief_catalog,relief,sources,sources,"task");if(!result.ok){std::cerr<<result.error.original.code<<"\n";std::abort();}sources.source.acceptance.relief_terms_id=result.value.id;check();}
    void ready(){sources.source.task_status="ready";sources.source.work=GovernanceWorkCompletion{"work","task","contract","action","accept","outcome",0,6};assert(common.append_fact({"work","governance_work_completed","tasks"}).ok&&common.append_fact({"outcome","governance_outcome_plan","politics"}).ok);common.state().identity.tick=6;}
    Outcome<GovernanceSettlementAttempt> settle(){return settle_public_relief(common,economy,relief,sources,sources,"task");}
    void finish(const StableId& receipt){GovernanceTaskCompletion f;f.fact_id="final";f.task_id="task";f.contract_id="contract";f.action_id="action";f.acceptance_fact_id="accept";f.work_completion_fact_id="work";f.outcome_plan_id="outcome";f.resource_receipt_ids={receipt};f.completed_tick=common.tick();sources.source.completion=f;sources.source.task_status="success";assert(common.append_fact({"final","governance_task_completed","tasks"}).ok);check();}
    void check(){auto s=validate_public_relief(common,economy,relief_catalog,relief,sources,sources);if(!s.ok){std::cerr<<s.error.original.code<<"\n";std::abort();}}
};
// 足额前不写预留；固定成本少一钱、未授权或家庭产权不匹配均保原资产和ID。
void relief_admission(){
    ReliefFixture f;auto before=encode_common_state(f.common.state());auto quote=preview_public_relief(f.common,f.economy,f.relief_catalog,f.relief,f.sources,f.sources,"task");assert(quote.ok&&compare_boundary(before,encode_common_state(f.common.state())).exact());
    f.sources.permit=false;assert(!preview_public_relief(f.common,f.economy,f.relief_catalog,f.relief,f.sources,f.sources,"task").ok);f.sources.permit=true;
    f.relief_catalog.policies.find("aid")->recipients[0].cash=119;assert(!preview_public_relief(f.common,f.economy,f.relief_catalog,f.relief,f.sources,f.sources,"task").ok);f.relief_catalog.policies.find("aid")->recipients[0].cash=120;
    assert(f.common.apply_resources({{WalletDelta{"city.wallet",-1,true}},{}}).ok);before=encode_common_state(f.common.state());auto shortfall=reserve_public_relief(f.common,f.economy,f.relief_catalog,f.relief,f.sources,f.sources,"task");assert(!shortfall.ok&&shortfall.error.original.code=="InsufficientReliefFunds"&&f.relief.commitments.empty()&&compare_boundary(before,encode_common_state(f.common.state())).exact());
    assert(f.common.apply_resources({{WalletDelta{"city.wallet",1,true}},{}}).ok);f.reserve();assert(f.common.wallet("city.wallet")->balance==120&&f.common.spendable("city.wallet").value==0&&f.common.count("city.inventory","grain",{{Owner::Kind::organization,"city",{}}}).value==10);assert(!reserve_public_relief(f.common,f.economy,f.relief_catalog,f.relief,f.sources,f.sources,"task").ok);
}
// 容量阻塞保留原预留；真实工作源、显式连续性和完整受领全部满足才一次转账。
void relief_distribution(){
    ReliefFixture f;f.reserve();assert(!f.settle().ok);f.ready();auto before=encode_common_state(f.common.state());f.sources.continuity_missing=true;auto missing=f.settle();assert(!missing.ok&&missing.error.original.code=="MissingTestContinuity"&&compare_boundary(before,encode_common_state(f.common.state())).exact());
    f.sources.continuity_missing=false;f.sources.continuity=GovernanceContinuityKind::needs_reassignment;auto denied=f.settle();assert(denied.ok&&denied.value.kind==GovernanceSettlementAttempt::Kind::pending&&denied.value.code=="NeedsReassignment");f.sources.continuity=GovernanceContinuityKind::continue_work;
    assert(f.common.apply_resources({{SetInventoryCapacity{"family.inventory",9}},{}}).ok);before=encode_common_state(f.common.state());auto pending=f.settle();assert(pending.ok&&pending.value.kind==GovernanceSettlementAttempt::Kind::pending&&pending.value.resource_receipt_ids.empty()&&pending.value.code=="ReliefRecipientInventoryFull"&&compare_boundary(before,encode_common_state(f.common.state())).exact());
    assert(f.common.apply_resources({{SetInventoryCapacity{"family.inventory",100}},{}}).ok);auto paid=f.settle();assert(paid.ok&&paid.value.resource_receipt_ids.size()==1&&f.common.wallet("city.wallet")->balance==0&&f.common.wallet("family.wallet")->balance==120&&f.common.count("family.inventory","grain",{{Owner::Kind::household,"family",{}}}).value==10&&f.common.count("city.inventory","grain",{{Owner::Kind::organization,"city",{}}}).value==10);before=encode_common_state(f.common.state());auto repeat=f.settle();assert(repeat.ok&&repeat.value.resource_receipt_ids==paid.value.resource_receipt_ids&&compare_boundary(before,encode_common_state(f.common.state())).exact());assert(!release_public_relief(f.common,f.relief,f.sources,"task").ok);f.finish(paid.value.resource_receipt_ids[0]);
    auto wire=encode_public_relief_state(f.relief);auto restored=decode_public_relief_state(wire);assert(restored.ok&&compare_boundary(wire,encode_public_relief_state(restored.value)).exact());CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);auto state=f.relief;assert(visit_public_relief_checkpoint(writer,state).ok&&writer.finish().ok);const auto& input=bytes;CodecVisitor reader(input);PublicReliefState cold;assert(visit_public_relief_checkpoint(reader,cold).ok&&reader.finish().ok&&compare_boundary(wire,encode_public_relief_state(cold)).exact());f.relief=cold;f.check();
    auto broken=f.relief;broken.receipts.rows()[0].second.cash_transferred-=1;assert(!validate_public_relief(f.common,f.economy,f.relief_catalog,broken,f.sources,f.sources).ok);wire.find("version")->data=true;assert(!decode_public_relief_state(wire).ok);
}
// 一份计划有两个家庭时，第二家受阻不能先给第一家；primitive错误回滚整份recipe和ID。
void relief_atomic_plan(){
    ReliefFixture f;Owner owner{Owner::Kind::household,"family2",{}};assert(f.common.apply_resources({{CreateWallet{{"family2.wallet",owner,0,{}}},CreateInventory{{"family2.inventory",owner,4,0,{}}}},{}}).ok);f.economy.households.insert("family2",{"family2","family2.wallet","family2.inventory"});auto c=*f.economy.cohorts.find("workers");c.id="workers2";c.household_group_id="family2";c.private_wallet_id="family2.wallet";c.private_inventory_id="family2.inventory";f.economy.cohorts.insert(c.id,c);f.relief_catalog.policies.find("aid")->recipients={{"family","workers",60,5},{"family2","workers2",60,5}};f.reserve();f.ready();auto before=encode_common_state(f.common.state());assert(f.settle().value.kind==GovernanceSettlementAttempt::Kind::pending&&compare_boundary(before,encode_common_state(f.common.state())).exact());assert(f.common.apply_resources({{SetInventoryCapacity{"family2.inventory",10}},{}}).ok);
    f.common.state().next_instance_id=INT64_MAX;before=encode_common_state(f.common.state());auto failed=f.settle();assert(!failed.ok&&failed.error.original.code=="InstanceIdOverflow"&&f.relief.receipts.empty()&&compare_boundary(before,encode_common_state(f.common.state())).exact());
}
// 取消只退本合同预留，旁支预留和实际公粮完整保留；不得倒扣已发给家庭的钱粮。
void relief_cancellation(){
    ReliefFixture f;assert(f.common.apply_resources({{WalletDelta{"city.wallet",10,true},SetReservation{"city.wallet",{ReservationRef::Kind::contract,"other"},10,false},ReserveLots{"city.inventory","grain",2,{{Owner::Kind::organization,"city",{}}},{ReservationRef::Kind::contract,"other"}}},{}}).ok);f.reserve();assert(release_public_relief(f.common,f.relief,f.sources,"task").ok);assert(f.common.wallet("city.wallet")->balance==130&&f.common.spendable("city.wallet").value==120&&f.common.count("city.inventory","grain",{{Owner::Kind::organization,"city",{}}},{ReservationRef::Kind::contract,"other"}).value==2);const auto before=encode_common_state(f.common.state());assert(release_public_relief(f.common,f.relief,f.sources,"task").ok&&compare_boundary(before,encode_common_state(f.common.state())).exact());GovernanceTaskCompletion final;final.fact_id="cancel";final.task_id="task";final.contract_id="contract";final.action_id="action";final.acceptance_fact_id="accept";assert(f.common.append_fact({"cancel","governance_task_cancelled","tasks"}).ok);final.result=GovernanceTaskResult::cancelled;final.completed_tick=0;f.sources.source.completion=final;f.sources.source.task_status="cancelled";f.check();
}
// 公库换属明确待改派，不能在历史条款核验时先硬失败；未完劳动中断释放记原to_tick并保责任。
void relief_continuity_and_interruption(){
    ReliefFixture moved;moved.reserve();moved.ready();moved.sources.continuity=GovernanceContinuityKind::needs_reassignment;const Owner successor{Owner::Kind::organization,"successor",{}};assert(moved.common.apply_resources({{SetWalletOwner{"city.wallet",successor},SetInventoryOwner{"city.inventory",successor}},{}}).ok);const auto before=encode_common_state(moved.common.state());auto pending=moved.settle();assert(pending.ok&&pending.value.kind==GovernanceSettlementAttempt::Kind::pending&&pending.value.code=="NeedsReassignment"&&compare_boundary(before,encode_common_state(moved.common.state())).exact());moved.check();
    moved.sources.continuity=static_cast<GovernanceContinuityKind>(99);auto unknown=moved.settle();assert(!unknown.ok&&unknown.error.original.code=="UnknownGovernanceContinuity");
    ReliefFixture stopped;stopped.reserve();ActorMutation death;death.actor_id="mayor";death.alive=false;assert(stopped.common.apply_actor(death).ok);DynamicStepInput phase{0,1,{},{},{}};assert(release_public_relief(stopped.common,stopped.relief,stopped.sources,"task",&phase).ok);assert(stopped.relief.releases.rows()[0].second.tick==1);
    assert(stopped.common.append_fact({"interruption","governance_work_interrupted","tasks"}).ok);stopped.sources.source.interruption=GovernanceWorkInterruption{"interruption","task","contract","action","accept","ExecutorDead",1,0};stopped.sources.source.task_status="settling";stopped.common.state().identity.tick=1;stopped.check();assert(!stopped.sources.source.completion&&stopped.common.wallet("city.wallet")->balance==120&&stopped.common.wallet("family.wallet")->balance==0);
    auto wrong=stopped.sources;wrong.source.interruption->stopped_tick=0;assert(!validate_public_relief(stopped.common,stopped.economy,stopped.relief_catalog,stopped.relief,wrong,wrong).ok);DynamicStepInput future{1,3,{},{},{}};assert(!release_public_relief(stopped.common,stopped.relief,stopped.sources,"task",&future).ok);
}
// NPC原保存点包住准入、分发或取消时，领域不再嵌套；后续任务失败能撤回钱粮及typed责任。
void relief_outer_candidate(){
    ReliefFixture admission;auto before=encode_common_state(admission.common.state());auto original=admission.relief;auto mark=admission.common.begin_savepoint();assert(mark.ok);auto held=reserve_public_relief_in_candidate(admission.common,admission.economy,admission.relief_catalog,admission.relief,admission.sources,admission.sources,"task");assert(held.ok&&admission.common.spendable("city.wallet").value==0);assert(admission.common.rollback_savepoint(mark.value).ok);admission.relief=original;assert(compare_boundary(before,encode_common_state(admission.common.state())).exact()&&admission.relief.commitments.empty());
    ReliefFixture payout;payout.reserve();payout.ready();before=encode_common_state(payout.common.state());original=payout.relief;mark=payout.common.begin_savepoint();assert(mark.ok);auto sent=settle_public_relief_in_candidate(payout.common,payout.economy,payout.relief,payout.sources,payout.sources,"task");assert(sent.ok&&sent.value.kind==GovernanceSettlementAttempt::Kind::settled&&payout.common.wallet("family.wallet")->balance==120);assert(payout.common.rollback_savepoint(mark.value).ok);payout.relief=original;assert(compare_boundary(before,encode_common_state(payout.common.state())).exact()&&payout.relief.receipts.empty());payout.check();
    ReliefFixture cancel;cancel.reserve();before=encode_common_state(cancel.common.state());original=cancel.relief;mark=cancel.common.begin_savepoint();assert(mark.ok&&release_public_relief_in_candidate(cancel.common,cancel.relief,cancel.sources,"task").ok);assert(cancel.common.rollback_savepoint(mark.value).ok);cancel.relief=original;assert(compare_boundary(before,encode_common_state(cancel.common.state())).exact()&&cancel.relief.releases.empty());cancel.check();
}
